/* ===== ChartPulse — Shared Styles ===== */
:root {
  --bg-primary: #0F0F0F;
  --bg-secondary: #1a1a2e;
  --bg-card: #1a1a2e;
  --bg-surface: #16213e;
  --bg-hover: #1e1e3a;
  --text-primary: #e8e8f0;
  --text-secondary: #8892b0;
  --text-muted: #5a6080;
  --accent-blue: #2962FF;
  --accent-teal: #00bfa5;
  --negative-red: #F7525F;
  --positive-green: #00c853;
  --border-color: #2a2a4a;
  --border-subtle: #1e1e38;
  --badge-green: rgba(0, 200, 83, 0.15);
  --badge-red: rgba(247, 82, 95, 0.15);
  --font: 'Inter', 'DM Sans', 'Segoe UI', system-ui, -apple-system, sans-serif;
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --shadow-card: 0 2px 8px rgba(0,0,0,0.3);
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  background: var(--bg-primary);
  color: var(--text-primary);
  font-family: var(--font);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

a { color: var(--accent-blue); text-decoration: none; }
a:hover { text-decoration: underline; }

/* ===== Navigation ===== */
.nav {
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 100;
  padding: 0 24px;
}
.nav-inner {
  max-width: 1400px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  height: 56px;
  gap: 8px;
}
.nav-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 20px;
  font-weight: 700;
  color: var(--text-primary);
  margin-right: 24px;
  white-space: nowrap;
}
.nav-brand .logo-icon {
  width: 32px;
  height: 32px;
  background: var(--accent-blue);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
}
.nav-links {
  display: flex;
  gap: 4px;
  list-style: none;
}
.nav-links a {
  color: var(--text-secondary);
  padding: 6px 14px;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 500;
  transition: all 0.15s;
  display: block;
}
.nav-links a:hover,
.nav-links a.active {
  color: var(--text-primary);
  background: var(--bg-hover);
  text-decoration: none;
}
.nav-actions {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 10px;
}
.nav-actions .btn-signup {
  background: var(--accent-blue);
  color: #fff;
  border: none;
  padding: 8px 18px;
  border-radius: var(--radius-sm);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: opacity 0.15s;
}
.nav-actions .btn-signup:hover { opacity: 0.9; }
.nav-actions .btn-login {
  background: transparent;
  color: var(--text-primary);
  border: none;
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
}
.nav-search {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  padding: 7px 12px;
  border-radius: var(--radius-sm);
  font-size: 13px;
  width: 180px;
  outline: none;
}
.nav-search::placeholder { color: var(--text-muted); }
.nav-search:focus { border-color: var(--accent-blue); }

/* ===== Layout ===== */
.container { max-width: 1400px; margin: 0 auto; padding: 0 24px; }
.section { padding: 40px 0; }
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}
.section-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--text-primary);
}
.section-subtitle {
  font-size: 13px;
  color: var(--text-secondary);
  margin-top: 2px;
}

/* ===== Hero ===== */
.hero {
  padding: 60px 0 40px;
  text-align: center;
}
.hero h1 {
  font-size: 48px;
  font-weight: 800;
  line-height: 1.15;
  max-width: 700px;
  margin: 0 auto 16px;
  background: linear-gradient(135deg, #fff 30%, var(--accent-blue) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.hero p {
  font-size: 17px;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto 28px;
  line-height: 1.6;
}
.hero-actions { display: flex; gap: 12px; justify-content: center; }
.btn { padding: 10px 24px; border-radius: var(--radius-sm); font-size: 14px; font-weight: 600; cursor: pointer; border: none; transition: all 0.15s; }
.btn-primary { background: var(--accent-blue); color: #fff; }
.btn-primary:hover { opacity: 0.9; }
.btn-outline { background: transparent; color: var(--text-primary); border: 1px solid var(--border-color); }
.btn-outline:hover { background: var(--bg-hover); }
.btn-sm { padding: 6px 14px; font-size: 12px; }
.btn-xs { padding: 3px 10px; font-size: 11px; border-radius: 4px; }

/* ===== Market Summary Bar ===== */
.market-bar {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  overflow-x: auto;
  white-space: nowrap;
  padding: 0;
}
.market-bar-inner {
  display: flex;
  gap: 0;
  padding: 0 24px;
  max-width: 1400px;
  margin: 0 auto;
}
.market-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  font-size: 13px;
  border-right: 1px solid var(--border-subtle);
  flex-shrink: 0;
  cursor: pointer;
  transition: background 0.15s;
}
.market-item:hover { background: var(--bg-hover); }
.market-item .ticker { font-weight: 700; color: var(--text-primary); }
.market-item .price { color: var(--text-secondary); font-variant-numeric: tabular-nums; }
.market-item .change { font-weight: 600; font-variant-numeric: tabular-nums; }
.market-item .change.up { color: var(--positive-green); }
.market-item .change.down { color: var(--negative-red); }

/* ===== Tabs ===== */
.tabs {
  display: flex;
  gap: 4px;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 20px;
}
.tab {
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  border: none;
  background: none;
  border-bottom: 2px solid transparent;
  transition: all 0.15s;
  font-family: var(--font);
}
.tab:hover { color: var(--text-primary); }
.tab.active {
  color: var(--accent-blue);
  border-bottom-color: var(--accent-blue);
}
.tab-pill-group {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}
.tab-pill {
  padding: 6px 14px;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-secondary);
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 20px;
  cursor: pointer;
  transition: all 0.15s;
  font-family: var(--font);
}
.tab-pill:hover { color: var(--text-primary); border-color: var(--text-muted); }
.tab-pill.active { background: var(--accent-blue); color: #fff; border-color: var(--accent-blue); }

/* ===== Cards ===== */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  overflow: hidden;
}
.card-padding { padding: 20px; }
.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }

/* ===== Stat Cards ===== */
.stat-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 16px;
}
.stat-card .label {
  font-size: 11px;
  text-transform: uppercase;
  color: var(--text-muted);
  letter-spacing: 0.5px;
  margin-bottom: 4px;
}
.stat-card .value {
  font-size: 22px;
  font-weight: 700;
  color: var(--text-primary);
  font-variant-numeric: tabular-nums;
}
.stat-card .sub {
  font-size: 12px;
  color: var(--text-secondary);
  margin-top: 2px;
}

/* ===== Tables ===== */
.table-wrap { overflow-x: auto; }
table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}
table th {
  text-align: left;
  padding: 10px 12px;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--text-muted);
  font-weight: 600;
  border-bottom: 1px solid var(--border-color);
  white-space: nowrap;
}
table td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--border-subtle);
  color: var(--text-primary);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}
table tbody tr:hover { background: var(--bg-hover); }
table .text-right { text-align: right; }
table .text-center { text-align: center; }
table .change-up, .text-green { color: var(--positive-green); }
table .change-down, .text-red { color: var(--negative-red); }

/* ===== Badges ===== */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 8px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 600;
}
.badge-green { background: var(--badge-green); color: var(--positive-green); }
.badge-red { background: var(--badge-red); color: var(--negative-red); }
.badge-blue { background: rgba(41,98,255,0.15); color: var(--accent-blue); }
.badge-teal { background: rgba(0,191,165,0.15); color: var(--accent-teal); }
.badge-tier { padding: 2px 8px; border-radius: 3px; font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px; }
.badge-platinum { background: rgba(0,191,165,0.2); color: var(--accent-teal); }
.badge-gold { background: rgba(255,193,7,0.2); color: #ffc107; }

/* ===== Star Rating ===== */
.stars { color: #ffc107; font-size: 13px; letter-spacing: 1px; }
.stars .dim { color: var(--text-muted); }

/* ===== Sparkline ===== */
.sparkline { width: 80px; height: 28px; }

/* ===== Footer ===== */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  padding: 48px 0 32px;
  margin-top: 40px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 24px;
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 24px;
}
.footer-col h4 {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--text-secondary);
  margin-bottom: 12px;
  font-weight: 700;
}
.footer-col a {
  display: block;
  color: var(--text-muted);
  font-size: 13px;
  padding: 3px 0;
  transition: color 0.15s;
}
.footer-col a:hover { color: var(--text-primary); text-decoration: none; }
.footer-bottom {
  text-align: center;
  color: var(--text-muted);
  font-size: 12px;
  padding-top: 24px;
  margin-top: 24px;
  border-top: 1px solid var(--border-color);
  max-width: 1400px;
  margin-left: auto;
  margin-right: auto;
  padding-left: 24px;
  padding-right: 24px;
}

/* ===== Idea Cards ===== */
.idea-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: border-color 0.15s;
}
.idea-card:hover { border-color: var(--accent-blue); }
.idea-card-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border-subtle);
}
.idea-card-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--accent-blue);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 700;
  color: #fff;
}
.idea-card-user { font-size: 13px; font-weight: 600; }
.idea-card-time { font-size: 11px; color: var(--text-muted); }
.idea-card-body { padding: 16px; }
.idea-card-title { font-size: 15px; font-weight: 700; margin-bottom: 8px; line-height: 1.3; }
.idea-card-text { font-size: 13px; color: var(--text-secondary); line-height: 1.5; }
.idea-card-tags { display: flex; gap: 6px; margin-top: 10px; flex-wrap: wrap; }
.idea-card-tag {
  padding: 3px 8px;
  font-size: 11px;
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  color: var(--text-secondary);
}
.idea-card-footer {
  display: flex;
  gap: 16px;
  padding: 10px 16px;
  border-top: 1px solid var(--border-subtle);
  font-size: 12px;
  color: var(--text-muted);
}
.idea-card-chart { padding: 8px 16px; height: 140px; background: var(--bg-surface); }

/* ===== Broker Card ===== */
.broker-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 20px;
  transition: border-color 0.15s;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.broker-card:hover { border-color: var(--accent-blue); }
.broker-card-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
}
.broker-card-name { font-size: 16px; font-weight: 700; }
.broker-card-rating {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
}
.broker-card-rating .score { font-size: 18px; font-weight: 700; }
.broker-card-stats {
  display: flex;
  gap: 16px;
  font-size: 13px;
  color: var(--text-secondary);
}
.broker-card-promo {
  background: var(--bg-surface);
  border-radius: var(--radius-sm);
  padding: 10px 12px;
  font-size: 12px;
  color: var(--accent-teal);
  font-weight: 500;
}
.broker-card-actions { display: flex; gap: 8px; margin-top: auto; }

/* ===== Chart Workspace ===== */
.chart-workspace {
  display: grid;
  grid-template-columns: 280px 1fr 320px;
  height: calc(100vh - 56px);
  overflow: hidden;
}
.chart-toolbar {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  padding: 8px 16px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.toolbar-btn {
  padding: 6px 12px;
  font-size: 12px;
  font-weight: 500;
  border: 1px solid var(--border-color);
  background: transparent;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.15s;
  font-family: var(--font);
  display: flex;
  align-items: center;
  gap: 4px;
}
.toolbar-btn:hover,
.toolbar-btn.active { background: var(--bg-hover); color: var(--text-primary); }
.toolbar-sep { width: 1px; height: 20px; background: var(--border-color); margin: 0 4px; }

.timeframe-btns { display: flex; gap: 2px; }
.tf-btn {
  padding: 5px 10px;
  font-size: 11px;
  font-weight: 600;
  border: none;
  background: transparent;
  color: var(--text-secondary);
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.15s;
  font-family: var(--font);
}
.tf-btn:hover { color: var(--text-primary); background: var(--bg-hover); }
.tf-btn.active { background: var(--accent-blue); color: #fff; }

/* ===== Watchlist ===== */
.watchlist { overflow-y: auto; background: var(--bg-secondary); border-right: 1px solid var(--border-color); }
.watchlist-header {
  padding: 12px 16px;
  font-size: 14px;
  font-weight: 700;
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  background: var(--bg-secondary);
  z-index: 2;
}
.wl-category { border-bottom: 1px solid var(--border-subtle); }
.wl-cat-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 16px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--text-secondary);
  cursor: pointer;
  transition: background 0.15s;
}
.wl-cat-header:hover { background: var(--bg-hover); }
.wl-cat-header .arrow { font-size: 10px; transition: transform 0.2s; }
.wl-cat-header .arrow.open { transform: rotate(90deg); }
.wl-items { display: none; }
.wl-items.open { display: block; }
.wl-row {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 4px;
  padding: 6px 16px;
  font-size: 12px;
  cursor: pointer;
  transition: background 0.1s;
  font-variant-numeric: tabular-nums;
}
.wl-row:hover { background: var(--bg-hover); }
.wl-row .sym { font-weight: 600; color: var(--text-primary); }
.wl-row .price { color: var(--text-secondary); text-align: right; }
.wl-row .chg { text-align: right; font-weight: 500; }
.wl-row .chg.up { color: var(--positive-green); }
.wl-row .chg.down { color: var(--negative-red); }

/* ===== Chart Area ===== */
.chart-main {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.chart-canvas-wrap {
  flex: 1;
  position: relative;
  background: var(--bg-primary);
}
.chart-canvas-wrap canvas {
  width: 100%;
  height: 100%;
}

/* ===== Detail Panel ===== */
.detail-panel {
  background: var(--bg-secondary);
  border-left: 1px solid var(--border-color);
  overflow-y: auto;
  font-size: 13px;
}
.detail-header {
  padding: 16px;
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  background: var(--bg-secondary);
  z-index: 2;
}
.detail-header .ticker-name { font-size: 20px; font-weight: 800; }
.detail-header .company { font-size: 12px; color: var(--text-secondary); }
.detail-header .price-big { font-size: 28px; font-weight: 800; margin-top: 4px; font-variant-numeric: tabular-nums; }
.detail-header .change-line { font-size: 13px; margin-top: 2px; }
.detail-section { padding: 16px; border-bottom: 1px solid var(--border-subtle); }
.detail-section h4 {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--text-muted);
  margin-bottom: 10px;
}
.detail-row {
  display: flex;
  justify-content: space-between;
  padding: 4px 0;
  font-size: 12px;
}
.detail-row .dl { color: var(--text-secondary); }
.detail-row .dv { font-weight: 500; font-variant-numeric: tabular-nums; }
.detail-headline {
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.5;
  padding: 12px 16px;
  background: var(--bg-surface);
  border-radius: var(--radius-sm);
  margin-top: 8px;
}

/* ===== News Cards ===== */
.news-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: border-color 0.15s;
}
.news-card:hover { border-color: var(--accent-blue); }
.news-card-body { padding: 14px; }
.news-card-title { font-size: 14px; font-weight: 600; margin-bottom: 6px; line-height: 1.3; }
.news-card-meta { font-size: 11px; color: var(--text-muted); }
.news-card-source {
  display: inline-block;
  padding: 2px 6px;
  font-size: 10px;
  font-weight: 600;
  border-radius: 3px;
  background: var(--bg-surface);
  color: var(--text-secondary);
  margin-right: 6px;
}

/* ===== Indicators List ===== */
.indicator-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 0;
  border-bottom: 1px solid var(--border-subtle);
}
.indicator-item:last-child { border-bottom: none; }
.indicator-left { display: flex; align-items: center; gap: 10px; }
.indicator-icon {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  background: var(--bg-surface);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
}
.indicator-info .name { font-size: 13px; font-weight: 600; }
.indicator-info .author { font-size: 11px; color: var(--text-muted); }
.indicator-right { text-align: right; }
.indicator-right .uses { font-size: 11px; color: var(--text-secondary); }
.indicator-right .rating { font-size: 12px; color: #ffc107; }

/* ===== Earnings ===== */
.earnings-badge-surprise { color: var(--positive-green); font-weight: 600; }
.earnings-badge-miss { color: var(--negative-red); font-weight: 600; }
.earnings-badge-pending { color: var(--text-muted); }

/* ===== Pagination ===== */
.pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin-top: 24px;
}
.page-btn {
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border-color);
  background: transparent;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  font-size: 13px;
  cursor: pointer;
  transition: all 0.15s;
  font-family: var(--font);
}
.page-btn:hover { background: var(--bg-hover); color: var(--text-primary); }
