}
.yield-value { font-size: 12px; font-weight: 600; font-variant-numeric: tabular-nums; width: 60px; text-align: right; }

/* ===== Responsive ===== */
@media (max-width: 1200px) {
  .chart-workspace { grid-template-columns: 240px 1fr 280px; }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
