.badge-green { background: var(--badge-green); color: var(--positive-green); }
.badge-red { background: var(--badge-red); color: var(--negative-red); }
.badge-blue { background: rgba(41,98,255,0.15); color: var(--accent-blue); }
.badge-teal { background: rgba(0,191,165,0.15); color: var(--accent-teal); }
