/* ===== Star Rating ===== */
.stars { color: #ffc107; font-size: 13px; letter-spacing: 1px; }
.stars .dim { color: var(--text-muted); }

/* ===== Sparkline ===== */
.sparkline { width: 80px; height: 28px; }

/* ===== Footer ===== */
.footer {
