.wl-row .sym { font-weight: 600; color: var(--text-primary); }
.wl-row .price { color: var(--text-secondary); text-align: right; }
.wl-row .chg { text-align: right; font-weight: 500; }
.wl-row .chg.up { color: var(--positive-green); }
.wl-row .chg.down { color: var(--negative-red); }

/* ===== Chart Area ===== */
.chart-main {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.chart-canvas-wrap {
  flex: 1;
  position: relative;
  background: var(--bg-primary);
}
.chart-canvas-wrap canvas {
  width: 100%;
  height: 100%;
}

/* ===== Detail Panel ===== */
.detail-panel {
  background: var(--bg-secondary);
  border-left: 1px solid var(--border-color);
  overflow-y: auto;
  font-size: 13px;
}
.detail-header {
  padding: 16px;
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  background: var(--bg-secondary);
  z-index: 2;
}
.detail-header .ticker-name { font-size: 20px; font-weight: 800; }
.detail-header .company { font-size: 12px; color: var(--text-secondary); }
.detail-header .price-big { font-size: 28px; font-weight: 800; margin-top: 4px; font-variant-numeric: tabular-nums; }
.detail-header .change-line { font-size: 13px; margin-top: 2px; }
.detail-section { padding: 16px; border-bottom: 1px solid var(--border-subtle); }
.detail-section h4 {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--text-muted);
  margin-bottom: 10px;
}
.detail-row {
  display: flex;
  justify-content: space-between;
  padding: 4px 0;
  font-size: 12px;
}
.detail-row .dl { color: var(--text-secondary); }
.detail-row .dv { font-weight: 500; font-variant-numeric: tabular-nums; }
.detail-headline {
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.5;
  padding: 12px 16px;
  background: var(--bg-surface);
  border-radius: var(--radius-sm);
  margin-top: 8px;
}

/* ===== News Cards ===== */
.news-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: border-color 0.15s;
}
.news-card:hover { border-color: var(--accent-blue); }
.news-card-body { padding: 14px; }
.news-card-title { font-size: 14px; font-weight: 600; margin-bottom: 6px; line-height: 1.3; }
.news-card-meta { font-size: 11px; color: var(--text-muted); }
.news-card-source {
  display: inline-block;
  padding: 2px 6px;
  font-size: 10px;
  font-weight: 600;
  border-radius: 3px;
  background: var(--bg-surface);
  color: var(--text-secondary);
  margin-right: 6px;
}

/* ===== Indicators List ===== */
.indicator-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 0;
  border-bottom: 1px solid var(--border-subtle);
}
.indicator-item:last-child { border-bottom: none; }
.indicator-left { display: flex; align-items: center; gap: 10px; }
.indicator-icon {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  background: var(--bg-surface);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
}
.indicator-info .name { font-size: 13px; font-weight: 600; }
.indicator-info .author { font-size: 11px; color: var(--text-muted); }
.indicator-right { text-align: right; }
.indicator-right .uses { font-size: 11px; color: var(--text-secondary); }
.indicator-right .rating { font-size: 12px; color: #ffc107; }

/* ===== Earnings ===== */
.earnings-badge-surprise { color: var(--positive-green); font-weight: 600; }
.earnings-badge-miss { color: var(--negative-red); font-weight: 600; }
.earnings-badge-pending { color: var(--text-muted); }

/* ===== Pagination ===== */
.pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin-top: 24px;
}
.page-btn {
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border-color);
  background: transparent;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  font-size: 13px;
  cursor: pointer;
  transition: all 0.15s;
  font-family: var(--font);
}
.page-btn:hover { background: var(--bg-hover); color: var(--text-primary); }
.page-btn.active { background: var(--accent-blue); color: #fff; border-color: var(--accent-blue); }

/* ===== Stats Banner ===== */
.stats-banner {
  background: linear-gradient(135deg, var(--accent-blue), #1a237e);
  padding: 40px 24px;
  text-align: center;
  border-radius: var(--radius-lg);
  margin: 24px 0;
}
.stats-banner .stats-grid {
  display: flex;
  justify-content: center;
  gap: 60px;
}
.stats-banner .stat-num {
  font-size: 36px;
  font-weight: 800;
  color: #fff;
}
.stats-banner .stat-label {
  font-size: 14px;
  color: rgba(255,255,255,0.7);
  margin-top: 4px;
}

/* ===== Featured Banner ===== */
.featured-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 8px;
  border-radius: 4px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  background: rgba(255,193,7,0.2);
  color: #ffc107;
}

/* ===== Market Page Tabs ===== */
.market-nav-tabs {
  display: flex;
  gap: 2px;
  overflow-x: auto;
  padding: 0;
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 56px;
  background: var(--bg-primary);
  z-index: 50;
}
.market-nav-tab {
  padding: 10px 16px;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
  cursor: pointer;
  border: none;
  background: none;
  border-bottom: 2px solid transparent;
  white-space: nowrap;
  transition: all 0.15s;
  font-family: var(--font);
  text-transform: uppercase;
  letter-spacing: 0.3px;
}
.market-nav-tab:hover { color: var(--text-primary); }
.market-nav-tab.active { color: var(--accent-blue); border-bottom-color: var(--accent-blue); }

/* ===== Mini Charts in Markets ===== */
.mini-chart { width: 100px; height: 32px; }

/* ===== Gainers/Losers ===== */
.mover-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 0;
  border-bottom: 1px solid var(--border-subtle);
}
.mover-row:last-child { border-bottom: none; }
.mover-rank { width: 24px; font-size: 12px; color: var(--text-muted); }
.mover-name { flex: 1; font-size: 13px; font-weight: 500; }

/* ===== Bond yield curve ===== */
.yield-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 0;
}
.yield-tenor { font-size: 12px; color: var(--text-secondary); width: 50px; font-weight: 600; }
.yield-bar {
  height: 6px;
  background: var(--accent-blue);
  border-radius: 3px;
  transition: width 0.3s;
}
.yield-value { font-size: 12px; font-weight: 600; font-variant-numeric: tabular-nums; width: 60px; text-align: right; }

/* ===== Responsive ===== */
@media (max-width: 1200px) {
  .chart-workspace { grid-template-columns: 240px 1fr 280px; }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 900px) {
  .chart-workspace { grid-template-columns: 1fr; grid-template-rows: auto 1fr auto; }
  .watchlist { max-height: 200px; border-right: none; border-bottom: 1px solid var(--border-color); }
  .detail-panel { border-left: none; border-top: 1px solid var(--border-color); max-height: 300px; }
  .grid-3, .grid-2 { grid-template-columns: 1fr; }
  .grid-4 { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .hero h1 { font-size: 32px; }
  .stats-banner .stats-grid { gap: 24px; flex-wrap: wrap; }
}
@media (max-width: 600px) {
  .nav-links { display: none; }
  .grid-4 { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .market-bar-inner { padding: 0 8px; }
  .market-item { padding: 8px 10px; font-size: 11px; }
}
