/* ===== ChartPulse — Shared Styles ===== */
:root {
  --bg-primary: #0F0F0F;
  --bg-secondary: #1a1a2e;
  --bg-card: #1a1a2e;
  --bg-surface: #16213e;
  --bg-hover: #1e1e3a;
  --text-primary: #e8e8f0;
  --text-secondary: #8892b0;
  --text-muted: #5a6080;
  --accent-blue: #2962FF;
  --accent-teal: #00bfa5;
  --negative-red: #F7525F;
  --positive-green: #00c853;
  --border-color: #2a2a4a;
  --border-subtle: #1e1e38;
  --badge-green: rgba(0, 200, 83, 0.15);
  --badge-red: rgba(247, 82, 95, 0.15);
  --font: 'Inter', 'DM Sans', 'Segoe UI', system-ui, -apple-system, sans-serif;
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --shadow-card: 0 2px 8px rgba(0,0,0,0.3);
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  background: var(--bg-primary);
  color: var(--text-primary);
  font-family: var(--font);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

a { color: var(--accent-blue); text-decoration: none; }
a:hover { text-decoration: underline; }

/* ===== Navigation ===== */
.nav {
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 100;
  padding: 0 24px;
}
.nav-inner {
  max-width: 1400px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  height: 56px;
  gap: 8px;
}
.nav-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 20px;
  font-weight: 700;
  color: var(--text-primary);
  margin-right: 24px;
  white-space: nowrap;
}
.nav-brand .logo-icon {
  width: 32px;
  height: 32px;
  background: var(--accent-blue);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
}
.nav-links {
  display: flex;
  gap: 4px;
  list-style: none;
}
.nav-links a {
  color: var(--text-secondary);
  padding: 6px 14px;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 500;
  transition: all 0.15s;
  display: block;
}
.nav-links a:hover,
.nav-links a.active {
  color: var(--text-primary);
  background: var(--bg-hover);
  text-decoration: none;
}
.nav-actions {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 10px;
}
.nav-actions .btn-signup {
  background: var(--accent-blue);
  color: #fff;
  border: none;
  padding: 8px 18px;
  border-radius: var(--radius-sm);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: opacity 0.15s;
}
.nav-actions .btn-signup:hover { opacity: 0.9; }
.nav-actions .btn-login {
  background: transparent;
  color: var(--text-primary);
  border: none;
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
}
.nav-search {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  padding: 7px 12px;
  border-radius: var(--radius-sm);
  font-size: 13px;
  width: 180px;
  outline: none;
}
.nav-search::placeholder { color: var(--text-muted); }
.nav-search:focus { border-color: var(--accent-blue); }

/* ===== Layout ===== */
.container { max-width: 1400px; margin: 0 auto; padding: 0 24px; }
.section { padding: 40px 0; }
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}
.section-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--text-primary);
}
.section-subtitle {
  font-size: 13px;
  color: var(--text-secondary);
  margin-top: 2px;
}

/* ===== Hero ===== */
.hero {
  padding: 60px 0 40px;
  text-align: center;
}
.hero h1 {
  font-size: 48px;
  font-weight: 800;
  line-height: 1.15;
  max-width: 700px;
  margin: 0 auto 16px;
  background: linear-gradient(135deg, #fff 30%, var(--accent-blue) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.hero p {
  font-size: 17px;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto 28px;
  line-height: 1.6;
}
.hero-actions { display: flex; gap: 12px; justify-content: center; }
.btn { padding: 10px 24px; border-radius: var(--radius-sm); font-size: 14px; font-weight: 600; cursor: pointer; border: none; transition: all 0.15s; }
.btn-primary { background: var(--accent-blue); color: #fff; }
.btn-primary:hover { opacity: 0.9; }
.btn-outline { background: transparent; color: var(--text-primary); border: 1px solid var(--border-color); }
.btn-outline:hover { background: var(--bg-hover); }
.btn-sm { padding: 6px 14px; font-size: 12px; }
.btn-xs { padding: 3px 10px; font-size: 11px; border-radius: 4px; }

/* ===== Market Summary Bar ===== */
.market-bar {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  overflow-x: auto;
  white-space: nowrap;
  padding: 0;
}
.market-bar-inner {
  display: flex;
  gap: 0;
  padding: 0 24px;
