// ===== Toolbar =====
document.getElementById('toolbar').addEventListener('click', function(e) {
  const btn = e.target.closest('button');
  if (!btn) return;

  if (btn.dataset.tool) {
    this.querySelectorAll('[data-tool]').forEach(b => b.classList.remove('active-tool'));
