  }
  if (btn.dataset.tf) {
    this.querySelectorAll('.tf-btn').forEach(b => b.classList.remove('active-tf'));
    btn.classList.add('active-tf');
    const periods = { '1D': 1, '5D': 5, '1M': 22, '3M': 66, '6M': 132, 'YTD': 88, '1Y': 252, '5Y': 1260, 'All': 0 };
    generateData(periods[btn.dataset.tf] || 252);
    drawChart();
  }
  if (btn.dataset.ind) {
    btn.classList.toggle('active-tool');
  }
});

// ===== Candlestick Chart =====
const canvas = document.getElementById('chart-canvas');
const ctx = canvas.getContext('2d');
const container = document.getElementById('chart-container');

let ohlcData = [];
let visibleData = [];
let chartMin = 0, chartMax = 0;

function resizeCanvas() {
  const rect = container.getBoundingClientRect();
  canvas.width = rect.width * window.devicePixelRatio;
  canvas.height = rect.height * window.devicePixelRatio;
  canvas.style.width = rect.width + 'px';
  canvas.style.height = rect.height + 'px';
  ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
}

function generateData(numBars) {
  let price = 263.40;
  ohlcData = [];
  const total = numBars || 252;
  for (let i = 0; i < total; i++) {
    const volatility = price * 0.015;
    const open = price;
    const close = open + (Math.random() - 0.48) * volatility;
    const high = Math.max(open, close) + Math.random() * volatility * 0.5;
    const low = Math.min(open, close) - Math.random() * volatility * 0.5;
    const volume = Math.floor(Math.random() * 20000000 + 20000000);
    ohlcData.push({ open, high, low, close, volume });
    price = close;
  }
  visibleData = ohlcData.slice(-Math.min(ohlcData.length, 120));
}

function drawChart() {
  const rect = container.getBoundingClientRect();
  const W = rect.width - 65;
  const H = rect.height - 30;
  const pad = { top: 10, right: 65, bottom: 30, left: 5 };
  const pw = W - pad.left - pad.right;
  const ph = H - pad.top - pad.bottom;

  canvas.width = rect.width * window.devicePixelRatio;
  canvas.height = rect.height * window.devicePixelRatio;
  canvas.style.width = rect.width + 'px';
  canvas.style.height = rect.height + 'px';
  ctx.setTransform(window.devicePixelRatio, 0, 0, window.devicePixelRatio, 0, 0);

  // Clear
  ctx.fillStyle = '#0a0a14';
  ctx.fillRect(0, 0, W, H);

  if (visibleData.length === 0) return;

  // Compute range
  const prices = visibleData.flatMap(d => [d.high, d.low]);
  chartMin = Math.min(...prices);
  chartMax = Math.max(...prices);
  const range = chartMax - chartMin || 1;
  const padY = range * 0.05;
  const yMin = chartMin - padY;
  const yMax = chartMax + padY;
  const yRange = yMax - yMin;

  const toX = i => pad.left + (i / (visibleData.length - 1 || 1)) * pw;
  const toY = p => pad.top + (1 - (p - yMin) / yRange) * ph;
  const candleW = Math.max(1, Math.min(pw / visibleData.length * 0.7, 12));

  // Grid lines
  ctx.strokeStyle = 'rgba(255,255,255,0.04)';
  ctx.lineWidth = 1;
  const gridLines = 6;
  for (let i = 0; i <= gridLines; i++) {
    const y = pad.top + (i / gridLines) * ph;
    ctx.beginPath();
    ctx.moveTo(pad.left, y);
    ctx.lineTo(W - pad.right, y);
    ctx.stroke();
    // Price labels
    const price = yMax - (i / gridLines) * yRange;
    ctx.fillStyle = '#5a6080';
    ctx.font = '10px Inter, sans-serif';
    ctx.textAlign = 'right';
    ctx.fillText(price.toFixed(2), W - 6, y + 3);
  }

  // Volume bars (bottom)
  const volMax = Math.max(...visibleData.map(d => d.volume));
  const volH = 40;
  const volY = H - pad.bottom - volH;
  visibleData.forEach((d, i) => {
    const x = toX(i);
    const bw = Math.max(1, candleW * 0.8);
    const h = (d.volume / volMax) * volH;
    ctx.fillStyle = d.close >= d.open ? 'rgba(0,200,83,0.3)' : 'rgba(247,82,95,0.3)';
    ctx.fillRect(x - bw / 2, volY + volH - h, bw, h);
  });

  // Candles
  visibleData.forEach((d, i) => {
    const x = toX(i);
    const isUp = d.close >= d.open;
    const color = isUp ? '#00c853' : '#F7525F';
    const bodyTop = toY(Math.max(d.open, d.close));
    const bodyBot = toY(Math.min(d.open, d.close));
    const bodyH = Math.max(1, bodyBot - bodyTop);

    // Wick
    ctx.strokeStyle = color;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x, toY(d.high));
    ctx.lineTo(x, toY(d.low));
    ctx.stroke();

    // Body
    ctx.fillStyle = isUp ? color : color;
    ctx.fillRect(x - candleW / 2, bodyTop, candleW, bodyH);
    if (!isUp) {
      ctx.strokeStyle = color;
      ctx.strokeRect(x - candleW / 2, bodyTop, candleW, bodyH);
    }
  });

  // MA line (50 period SMA)
  ctx.strokeStyle = '#ff9800';
  ctx.lineWidth = 1.5;
  ctx.setLineDash([4, 4]);
  ctx.beginPath();
  let firstPoint = true;
  for (let i = 49; i < visibleData.length; i++) {
    let sum = 0;
    for (let j = i - 49; j <= i; j++) sum += visibleData[j].close;
    const ma = sum / 50;
    const x = toX(i);
    const y = toY(ma);
    if (firstPoint) { ctx.moveTo(x, y); firstPoint = false; }
    else ctx.lineTo(x, y);
  }
  ctx.stroke();
  ctx.setLineDash([]);

  // MA label
  if (visibleData.length > 50) {
    let sum = 0;
    const last50 = visibleData.slice(-50);
    last50.forEach(d => sum += d.close);
    const lastMA = sum / 50;
    ctx.fillStyle = '#ff9800';
    ctx.font = '10px Inter, sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText('MA(50)', pad.left + 4, toY(lastMA) - 4);
  }

  // Price axis
  const axisEl = document.getElementById('price-axis');
  const axisPrices = [];
  for (let i = 0; i <= 5; i++) {
    axisPrices.push(yMax - (i / 5) * yRange);
  }
  axisEl.innerHTML = axisPrices.map(p => `<span>${p.toFixed(2)}</span>`).join('');
}

// ===== Init =====
renderWatchlist();
updateDetailPanel();
resizeCanvas();
generateData(252);
drawChart();

window.addEventListener('resize', () => {
  resizeCanvas();
  drawChart();
});

// Watchlist click selects symbol
document.getElementById('watchlist').addEventListener('click', function(e) {
  const row = e.target.closest('.wl-row');
  if (row && row.dataset.sym) {
    document.getElementById('symbol-display').textContent =
      row.dataset.sym + ' · ChartPulse';
    generateData(252);
    drawChart();
  }
});

// Keyboard: arrow keys scroll chart
document.addEventListener('keydown', function(e) {
  if (e.key === 'ArrowRight' && visibleData.length > 0 && ohlcData.length > visibleData.length) {
    const idx = ohlcData.indexOf(visibleData[0]);
    const newStart = Math.min(idx + 5, ohlcData.length - visibleData.length);
    visibleData = ohlcData.slice(newStart, newStart + visibleData.length);
    drawChart();
  } else if (e.key === 'ArrowLeft') {
    const idx = ohlcData.indexOf(visibleData[0]);
    const newStart = Math.max(0, idx - 5);
    visibleData = ohlcData.slice(newStart, newStart + visibleData.length);
