  const areaD = `${pathD} L${w - pad},${h - pad} L${pad},${h - pad} Z`;
  return `<svg width="${w}" height="${h}" class="mini-chart-canvas">
    <path d="${areaD}" fill="${fillColor}"/>
    <path d="${pathD}" fill="none" stroke="${color}" stroke-width="1.5"/>
  </svg>`;
}

